-- 专家可用时间与外部专家邀请治理。
-- 可用时间按周维护，邀请只负责登记/排队；未配置真实邮件或身份服务时明确为“未配置”，
-- 不调用外部地址，也不写入“已发送”。只有外部适配器取得真实回执后才能落“已发送”。
BEGIN;

CREATE TABLE IF NOT EXISTS "专家可用时间" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "专家编号" integer NOT NULL,
    "星期" smallint NOT NULL,
    "开始时间" time without time zone NOT NULL,
    "结束时间" time without time zone NOT NULL,
    "时区" varchar(64) NOT NULL DEFAULT 'Asia/Shanghai',
    "是否启用" boolean NOT NULL DEFAULT TRUE,
    "备注" varchar(500),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_专家可用时间" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_专家可用时间_专家" FOREIGN KEY ("专家编号") REFERENCES "人员" ("编号"),
    CONSTRAINT "fk_专家可用时间_建立人" FOREIGN KEY ("建立人编号") REFERENCES "人员" ("编号"),
    CONSTRAINT "ck_专家可用时间_星期" CHECK ("星期" BETWEEN 1 AND 7),
    CONSTRAINT "ck_专家可用时间_时间范围" CHECK ("开始时间" < "结束时间"),
    CONSTRAINT "ck_专家可用时间_时区" CHECK (length(btrim("时区")) BETWEEN 1 AND 64)
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_专家可用时间_专家星期时间"
    ON "专家可用时间" ("专家编号", "星期", "开始时间", "结束时间");
CREATE INDEX IF NOT EXISTS "ix_专家可用时间_专家启用"
    ON "专家可用时间" ("专家编号", "是否启用", "星期", "开始时间");

CREATE TABLE IF NOT EXISTS "外部专家邀请" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "专家编号" integer,
    "外部姓名" varchar(100) NOT NULL,
    "外部邮箱" varchar(320) NOT NULL,
    "外部机构" varchar(200),
    "邀请场景" varchar(100) NOT NULL,
    "流程模板编号" integer,
    "项目编号" integer,
    "外部系统编号" bigint,
    "状态" varchar(20) NOT NULL DEFAULT '未配置',
    "幂等键" varchar(200) NOT NULL,
    "请求负载" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "外部消息编号" varchar(200),
    "回执来源" varchar(20) NOT NULL DEFAULT '配置检查',
    "响应摘要" varchar(1000),
    "失败原因" varchar(1000),
    "创建人编号" integer NOT NULL,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "发送时间" timestamp without time zone,
    "完成时间" timestamp without time zone,
    CONSTRAINT "pk_外部专家邀请" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_外部专家邀请_专家" FOREIGN KEY ("专家编号") REFERENCES "人员" ("编号"),
    CONSTRAINT "fk_外部专家邀请_外部系统" FOREIGN KEY ("外部系统编号") REFERENCES "外部系统" ("编号"),
    CONSTRAINT "fk_外部专家邀请_创建人" FOREIGN KEY ("创建人编号") REFERENCES "人员" ("编号"),
    CONSTRAINT "ck_外部专家邀请_状态" CHECK ("状态" IN ('待发送','已发送','发送失败','未配置','已取消','已接受','已拒绝')),
    CONSTRAINT "ck_外部专家邀请_回执来源" CHECK ("回执来源" IN ('未核验','真实邮件服务','系统排队','配置检查','人工取消')),
    CONSTRAINT "ck_外部专家邀请_邮箱" CHECK ("外部邮箱" ~* '^[^[:space:]@]+@[^[:space:]@]+\\.[^[:space:]@]+$'),
    CONSTRAINT "ck_外部专家邀请_发送回执" CHECK (
        "状态" <> '已发送'
        OR ("回执来源" = '真实邮件服务' AND NULLIF(btrim("外部消息编号"), '') IS NOT NULL AND "发送时间" IS NOT NULL)
    ),
    CONSTRAINT "ck_外部专家邀请_失败原因" CHECK (
        "状态" <> '发送失败' OR NULLIF(btrim("失败原因"), '') IS NOT NULL
    ),
    CONSTRAINT "ck_外部专家邀请_负载" CHECK (jsonb_typeof("请求负载") = 'object')
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_外部专家邀请_幂等键"
    ON "外部专家邀请" ("幂等键");
CREATE INDEX IF NOT EXISTS "ix_外部专家邀请_状态时间"
    ON "外部专家邀请" ("状态", "创建时间" DESC, "编号" DESC);
CREATE INDEX IF NOT EXISTS "ix_外部专家邀请_专家"
    ON "外部专家邀请" ("专家编号", "创建时间" DESC);

CREATE TABLE IF NOT EXISTS "外部专家邀请审计" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "邀请编号" bigint NOT NULL,
    "原状态" varchar(20),
    "新状态" varchar(20) NOT NULL,
    "回执来源" varchar(20) NOT NULL,
    "外部消息编号" varchar(200),
    "说明" varchar(1000),
    "操作人编号" integer NOT NULL,
    "操作时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_外部专家邀请审计" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_外部专家邀请审计_邀请" FOREIGN KEY ("邀请编号") REFERENCES "外部专家邀请" ("编号"),
    CONSTRAINT "fk_外部专家邀请审计_操作人" FOREIGN KEY ("操作人编号") REFERENCES "人员" ("编号"),
    CONSTRAINT "ck_外部专家邀请审计_回执来源" CHECK ("回执来源" IN ('未核验','真实邮件服务','系统排队','配置检查','人工取消'))
);
CREATE INDEX IF NOT EXISTS "ix_外部专家邀请审计_邀请时间"
    ON "外部专家邀请审计" ("邀请编号", "操作时间" DESC, "编号" DESC);

CREATE OR REPLACE FUNCTION "fn_外部专家邀请审计"()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'INSERT' OR OLD."状态" IS DISTINCT FROM NEW."状态"
       OR OLD."回执来源" IS DISTINCT FROM NEW."回执来源"
       OR OLD."外部消息编号" IS DISTINCT FROM NEW."外部消息编号"
       OR OLD."响应摘要" IS DISTINCT FROM NEW."响应摘要"
       OR OLD."失败原因" IS DISTINCT FROM NEW."失败原因" THEN
        INSERT INTO "外部专家邀请审计" (
            "邀请编号", "原状态", "新状态", "回执来源", "外部消息编号", "说明", "操作人编号"
        ) VALUES (
            NEW."编号", CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD."状态" END,
            NEW."状态", NEW."回执来源", NEW."外部消息编号",
            COALESCE(NEW."响应摘要", NEW."失败原因"), NEW."创建人编号"
        );
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS "tr_外部专家邀请_审计" ON "外部专家邀请";
CREATE TRIGGER "tr_外部专家邀请_审计"
AFTER INSERT OR UPDATE ON "外部专家邀请"
FOR EACH ROW EXECUTE FUNCTION "fn_外部专家邀请审计"();

UPDATE "系统迁移版本"
   SET "版本" = 84,
       "脚本" = '084_expert_availability_and_invitation.sql',
       "检查摘要" = '增加专家可用时间、外部专家邀请队列、幂等键和真实回执审计；未配置时不发送不伪造成功',
       "应用时间" = CURRENT_TIMESTAMP
 WHERE "编号" = 1;

COMMIT;
